do

local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local b64lut = {}
for i=1,#b64chars do b64lut[string.byte(b64chars,i)] = i-1 end
local function b64decode(data)
    data = data:gsub("[^A-Za-z0-9+/=]", "")
    local out = {}
    local acc, bits = 0, 0
    local n = 0
    for i=1,#data do
        local c = string.byte(data,i)
        local v = b64lut[c]
        if v then
            acc = acc * 64 + v
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local div = 2 ^ bits
                local byte = math.floor(acc / div)
                acc = acc - byte * div
                n = n + 1
                out[n] = string.char(byte % 256)
            end
        end
    end
    return table.concat(out)
end

_G.__NOIR_B64DECODE = b64decode
local _b64 = ""
local _code = b64decode(_b64)
local _fn, _err = loadstring(_code)
if not _fn then error("Part1 decode failed: "..tostring(_err)) end
_fn()

end